import {COUNTRIES,SEGMENTS} from '/geography.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=v=>String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let csrf,state,registerMode=false,countries=['AR','UY','ES'],draft=new Set(),view='all',selected=new Set(),activeLead=null,polling=false,toastTimer,searchAfterConnect=false,assistantLogKey='';
const PAGE_BUILD='3.7.2';
let sounds=localStorage.getItem('nexo-sounds')==='true';
function beep(){if(!sounds)return;try{const ctx=new AudioContext(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=660;g.gain.setValueAtTime(.025,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.001,ctx.currentTime+.2);o.start();o.stop(ctx.currentTime+.2);setTimeout(()=>ctx.close(),300);}catch{}}
function toast(msg,error=false){$('#toast').textContent=msg;$('#toast').classList.toggle('error',error);$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,error?12000:6500);if(!error)beep();}
function closeDialogs(){$$('dialog[open]').forEach(d=>d.close());}
function showLogin(){closeDialogs();$('#workspace').hidden=true;$('#loginScreen').hidden=false;selected.clear();state=null;}
async function api(route,data={},retry=true){let r=await fetch('/api/'+route,{method:'POST',headers:{'content-type':'application/json','x-csrf-token':csrf},body:JSON.stringify(data)});if(r.status===403&&retry){try{const s=await(await fetch('/api/session')).json();if(s.csrf&&s.csrf!==csrf){csrf=s.csrf;return api(route,data,false);}}catch{}}const d=await r.json();if(r.status===401)showLogin();if(!r.ok)throw Error(d.error||'No se pudo completar la acción.');if(d.state){state=d.state;render();}return d;}
async function refresh(){const r=await fetch('/api/state');if(r.status===401){showLogin();return;}if(!r.ok)throw Error('No se pudo leer tu espacio.');state=await r.json();render();}
async function run(fn,button){if(button)button.disabled=true;try{await fn();}catch(e){toast(e.message,true);}finally{if(button)button.disabled=button.id==='sendInstagramTest'?(!instagramTestNonce||!$('#instagramTestConsent').checked):button.id==='connectOfficialInstagram'?['waiting','connecting'].includes(state?.officialInstagram?.status):button.id==='searchButton'&&['running','waiting'].includes(state?.search.status);}}
function loginMode(create){registerMode=create;$('#loginTitle').textContent=create?'Creá tu espacio.':'Tu espacio de clientes.';$('#loginHint').textContent=create?'Tus clientes y tu historial quedarán asociados a tu cuenta local.':'Entrá para recuperar tu planilla y tu historial.';$('#loginSubmit').textContent=create?'Crear mi espacio':'Entrar';$('#switchLogin').textContent=create?'Ya tengo una cuenta':'Crear una cuenta local';$('#loginPassword').minLength=create?10:1;$('#loginPassword').autocomplete=create?'new-password':'current-password';$('#loginError').textContent='';}
$('#switchLogin').onclick=()=>loginMode(!registerMode);
$('#loginForm').onsubmit=e=>{e.preventDefault();const b=e.submitter;run(async()=>{const f=new FormData(e.target);try{await api(registerMode?'register':'login',{name:f.get('name'),password:f.get('password'),remember:f.get('remember')==='on'});e.target.reset();$('#loginError').textContent='';await startWorkspace();}catch(err){$('#loginError').textContent=err.message;}},b);};
async function startWorkspace(){await refresh();if(!state)return;countries=[...state.settings.countries];$('#loginScreen').hidden=true;$('#workspace').hidden=false;$('#seed').value=state.settings.lastSeed?(/^https?:/.test(state.settings.lastSeed)?state.settings.lastSeed:'https://www.instagram.com/'+state.settings.lastSeed+'/'):'';$('#cities').value=state.settings.cities||'';$('#offer').value=state.settings.offer||'';segments=String(state.settings.segment||'Hoteles').split(/\s*,\s*/).filter(Boolean);segmentSummary();$('#businessTier').value=state.settings.businessTier||'premium';countrySummary();$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-selected',String(b.dataset.view===view));});render();}
function countrySummary(){const names=COUNTRIES.filter(c=>countries.includes(c.code)).map(c=>c.name);$('#countrySummary').textContent=names.length>3?names.length+' países':names.join(', ');}
function countryOptions(){const q=norm($('#countrySearch').value);$('#countryOptions').innerHTML=COUNTRIES.filter(c=>norm(c.name).includes(q)).map(c=>`<label><span>${esc(c.name)}</span><input type="checkbox" data-country="${c.code}" ${draft.has(c.code)?'checked':''}></label>`).join('');$('#countryCount').textContent=draft.size+' países seleccionados';$('#applyCountries').disabled=!draft.size;}
$('#countriesOpen').onclick=()=>{draft=new Set(countries);$('#countrySearch').value='';countryOptions();$('#countriesDialog').showModal();};$('#countrySearch').oninput=countryOptions;$('#countryOptions').onchange=e=>{const c=e.target.dataset.country;if(!c)return;e.target.checked?draft.add(c):draft.delete(c);$('#countryCount').textContent=draft.size+' países seleccionados';$('#applyCountries').disabled=!draft.size;};$$('[data-preset]').forEach(b=>b.onclick=()=>{draft=new Set(b.dataset.preset==='none'?[]:COUNTRIES.filter(c=>b.dataset.preset==='all'||c.region==='latam').map(c=>c.code));countryOptions();});$('#applyCountries').onclick=()=>run(async()=>{countries=[...draft];await api('settings',{countries});countrySummary();$('#countriesDialog').close();});
$('#filtersOpen').onclick=()=>{const open=$('#searchFilters').hidden;$('#searchFilters').hidden=!open;$('#filtersOpen').setAttribute('aria-expanded',String(open));};
function status(l){if(isActive(l)&&!contacted(l)&&!l.dnc)return ['Cuenta activa','muted'];if(available(l)&&!qualified(l))return ['Por verificar','review'];if(l.dnc)return ['No contactar','muted'];if(l.eventStatus==='uncertain'||l.eventStatus==='pending')return ['Revisar envío','warning'];if(contacted(l))return ['Enviado','sent'];if(l.block.includes('Cupo'))return ['Cupo alcanzado','warning'];return [l.approved?'Pendiente':'Por revisar',l.approved?'ready':'review'];}
const audit=l=>{try{return JSON.parse(l.qualification||'null');}catch{return null;}};
const activityOf=l=>{try{return JSON.parse(l.activity||'{}');}catch{return {};}},isActive=l=>activityOf(l).verdict==='active';
function activityLine(l){const a=activityOf(l),ago=a.days!=null?` · última publicación hace ${a.days} ${a.days===1?'día':'días'}`:'';return a.verdict==='active'?`Actividad: publica seguido${ago}${a.story?' · tiene una historia activa':''}. No se le escribe.`:a.verdict==='inactive'?`Actividad: poco activa${ago}.`:'Actividad: sin verificar. Abrí el perfil y fijate cuándo fue su última publicación.';}
const available=l=>!l.dnc&&!contacted(l)&&!isActive(l);
const qualified=l=>!!l.demo||audit(l)?.status==='ready';
const isSelectable=l=>!l.dnc&&!l.archived&&!l.eventStatus&&!isActive(l);
const contacted=l=>l.eventStatus==='sent'||/^(Espera|Ya contactado)/.test(l.block||'');
const isPending=l=>available(l)&&qualified(l);
const displayName=l=>String(String(l.name||'').replace('DEMO · ','')||'').replace(/\s*[•·]\s*Instagram( photos and videos| fotos y videos)?.*$/i,'').replace(/\s*\(@[^)]*\)?.*$/,'').replace(/\s+\|\s+.*$/,'').trim()||'@'+l.handle;
function copyText(text){try{const t=document.createElement('textarea');t.value=text;t.setAttribute('readonly','');t.style.position='fixed';t.style.opacity='0';document.body.appendChild(t);t.select();const ok=document.execCommand('copy');t.remove();if(ok)return Promise.resolve();}catch{}return navigator.clipboard.writeText(text);}
function openChat(handle){return api('open-chat',{handle}).catch(()=>window.open('https://ig.me/m/'+handle,'_blank','noopener'));}
const VIEW_HINTS={pending:'Verificados y listos para recibir tu propuesta, de mayor a menor afinidad.',sent:'Clientes a los que ya les enviaste una propuesta. No se les vuelve a escribir.',review:'Encontrados pero sin verificar. Tocá «Ver» para revisarlos antes de contactarlos.',all:'Todos los clientes guardados en tu planilla.'};
function date(v){return v&&Number.isFinite(Date.parse(v))?new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',year:'numeric',timeZone:'America/Argentina/Buenos_Aires'}).format(new Date(v)):'—';}
function filtered(){const term=norm($('#listSearch').value),country=$('#listCountry').value;return state.leads.filter(l=>(view==='all'||view==='pending'&&isPending(l)||view==='sent'&&l.eventStatus==='sent'||view==='review'&&available(l)&&!qualified(l))&&(country==='all'||country===l.country)&&norm([l.name,l.handle,l.city,l.country].join(' ')).includes(term));}
function render(){if(!state)return;state.email=state.email||{configured:false,user:'',counts:{daily:0,monthly:0},attachment:''};state.schedules=state.schedules||[];$('#profileName').textContent=state.user.name;$('#profileInitial').textContent=(state.user.name||'?').trim().charAt(0).toUpperCase();$('#focusTag').textContent=`${state.settings.segment} · ${state.settings.cities||state.settings.countries.length+(state.settings.countries.length===1?' país':' países')} · Español`;$('#accountTitle').textContent=state.user.name;$('#connectionSummary').textContent=state.claudeConnected?'Asistente opcional ↗':'Opciones de Claude';$('#emailStatus').textContent=state.email.configured?'· '+state.email.user:'· sin configurar';$('#attachmentName').textContent=state.email.attachment?'Adjunto: '+state.email.attachment:'Sin adjunto';$('#removeAttachment').hidden=!state.email.attachment;$('#instagramStatus').textContent=state.instagram?`@${state.instagram.username}${state.instagramPaused?' · Envíos pausados':''}`:'Sin conectar';$('#pendingCount').textContent=state.leads.filter(isPending).length;$('#reviewCount').textContent=state.leads.filter(l=>available(l)&&!qualified(l)).length;$('#sentCount').textContent=state.leads.filter(l=>l.eventStatus==='sent').length;$('#quotaSummary').textContent=`Instagram ${state.counts.daily}/${state.settings.daily} hoy · Email ${state.email.counts.daily}/${state.settings.emailDaily} hoy`;$('#demoNotice').hidden=!state.leads.some(l=>l.demo);const current=$('#listCountry').value;const names=[...new Set(state.leads.map(l=>l.country).filter(Boolean))].sort();$('#listCountry').innerHTML='<option value="all">Todos los países</option>'+names.map(n=>`<option>${esc(n)}</option>`).join('');if(names.includes(current))$('#listCountry').value=current;for(const id of [...selected]){const l=state.leads.find(l=>l.id===id);if(!l||!isSelectable(l))selected.delete(id);}renderOfficialInstagram();renderRows();renderActivity();friendlyStatus();renderAssistant();renderSchedules();if($('#leadDialog').open){updateProposalStatus();const active=state.leads.find(l=>l.id===activeLead);if(active)renderAudit(active);}}
function renderRows(){if(!state)return;$('#emptyState h2').textContent=view==='review'?'Nada pendiente de verificar.':view==='sent'?'Todavía no registraste envíos.':state.leads.length?'No hay clientes en esta vista.':'Tu planilla empieza acá.';$('#demoButton').hidden=state.leads.length>0;const rows=filtered();$('#leadRows').innerHTML=rows.map(l=>{const [label,kind]=status(l);return `<tr class="${l.eventStatus==='sent'?'contacted':''}"><td class="check-cell"><input type="checkbox" data-select="${l.id}" aria-label="Seleccionar ${esc(l.name)}" ${selected.has(l.id)?'checked':''} ${!isSelectable(l)?'disabled':''}></td><td><strong>${esc(displayName(l))}${l.demo?' <em>DEMO</em>':''}</strong><small><a href="https://www.instagram.com/${esc(l.handle)}/" target="_blank" rel="noreferrer">@${esc(l.handle)}</a> · ${esc(l.city||l.country)}${l.email?' · ✉ '+esc(l.email):''}</small></td><td><span class="score ${l.score>=80?'high':''}" title="${esc(l.score_reason||'Estimación de afinidad, no probabilidad de compra')}">${l.score}<small>/100</small></span></td><td class="message-preview"><strong>${esc(audit(l)?.label|| (l.demo?'Ejemplo ficticio':'Necesita revisión'))}</strong><small>${esc(audit(l)?.businessDetail||l.reason)}</small></td><td><span class="badge ${kind}">${esc(label)}</span>${contacted(l)?`<small>Contactado el ${esc(date(l.last))}</small>`:''}</td><td><button class="row-button" data-review="${l.id}">Ver ↗</button></td></tr>`;}).join('');$('.sheet-scroll').hidden=!rows.length;$('#emptyState').hidden=!!rows.length;$('#rowCount').textContent=rows.length+(rows.length===1?' cliente':' clientes')+' · mayor prioridad primero';$('#selectionBar').hidden=!selected.size;$('#selectionCount').textContent=selected.size+(selected.size===1?' cliente seleccionado':' clientes seleccionados');renderSteps();renderCounter();renderBatchPicker();$('#viewHint').textContent=VIEW_HINTS[view]||'';$('#startQueue').disabled=!selected.size;$('#manualInstagramSelection').disabled=!selected.size;$('#emailSelection').disabled=!selected.size;$('#scheduleSelection').disabled=!selected.size;const eligible=rows.filter(isSelectable);$('#selectAll').checked=eligible.length>0&&eligible.every(l=>selected.has(l.id));}
function renderActivity(){const search=state.search;$('#searchStatus .spinner').hidden=search.status!=='running';$('#searchStatus').hidden=search.status==='idle';$('#searchStatusTitle').textContent=search.status==='running'?`${search.found} / ${search.target||100} candidatos encontrados`:search.status==='waiting'?`${search.found} / ${search.target||100} guardados · Verificación pendiente`:search.status==='completed'?`${search.found<(search.target||100)?'Búsqueda incompleta':'Búsqueda completa'}: ${search.found} / ${search.target||100} candidatos`:`${search.found||0} candidatos guardados · ${search.stage}`;$('#searchStatusDetail').textContent=search.status==='waiting'?'Completá vos la verificación en la ventana de Edge; después pulsá Ya completé la verificación. Nexo continuará sin perder candidatos.':search.error||(search.status==='running'?[search.stage,search.profile?'Tu oferta: '+search.profile.services:''].filter(Boolean).join(' · '):search.profile?[search.summary,'Tu oferta: '+search.profile.services,search.review?search.review+' candidatos en Por verificar.':''].filter(Boolean).join(' · '):search.summary||'Los resultados están guardados en tu planilla.');if(search.error?.includes('Qué ofrecés')){$('#searchFilters').hidden=false;$('#filtersOpen').setAttribute('aria-expanded','true');}$('#stopSearch').hidden=search.status!=='running';$('#openSearchBrowser').hidden=search.status!=='waiting';$('#continueSearch').hidden=search.status!=='waiting';$('#stopSearch').hidden=!['running','waiting'].includes(search.status);$('#searchButton').disabled=['running','waiting'].includes(search.status);$('#searchButton').textContent=search.status==='waiting'?'Verificación pendiente':search.status==='running'?'Buscando…':'Buscar hasta 100 ↗';const q=state.queue;$('#queueStatus').hidden=['idle'].includes(q.status);const titles={running:'Enviando por prioridad',waiting:'Cupo alcanzado · espera automática',paused:'Cola pausada',completed:'Cola terminada'};$('#queueTitle').textContent=`${titles[q.status]||'Cola'} · ${q.sent||0} enviados`;$('#queueDetail').textContent=[q.reason,`${q.items?.length||0} pendientes en cola`,q.skipped?`${q.skipped} omitidos`:''].filter(Boolean).join(' · ');$('#pauseQueue').hidden=!['running','waiting'].includes(q.status);$('#resumeQueue').hidden=q.status!=='paused';}
async function saveFilters(){await api('settings',{countries,cities:$('#cities').value,offer:$('#offer').value,segment:segments.join(', '),businessTier:$('#businessTier').value,maxResults:100,lastSeed:$('#seed').value.trim()});}
function openConnection(){const ready=!!state.claudeConnected;$('#connectionReady').hidden=!ready;$('#connectionSetup').hidden=ready;$('#connectionError').textContent='';$('#claudeRequest').value=state.searchRequest||'';$('#connectionDialog').showModal();}
async function startSearch(){await saveFilters();await api('search',{seed:$('#seed').value});view='all';selected.clear();$$('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-selected',String(b.dataset.view===view));});renderRows();toast('Búsqueda iniciada en segundo plano. Si el buscador pide verificación, Nexo te avisará.');}
$('#searchForm').onsubmit=e=>{e.preventDefault();run(async()=>{await startSearch();},$('#searchButton'));};$('#connectionOpen').onclick=()=>{searchAfterConnect=false;if(state.claudeConnected){openAssistant();}else openConnection();};$('#copyClaudeRequest').onclick=()=>run(async()=>{await saveFilters();const response=await fetch('/api/search-request');const request=await response.json();if(!response.ok)throw Error(request.error||'No se pudo preparar la búsqueda.');const text=request.request;await navigator.clipboard.writeText(text);window.open('claude://','_blank');toast('Pedido copiado. Pegalo en una conversación nueva de Claude.');});$('#openSearchBrowser').onclick=()=>run(()=>api('search/browser'));$('#continueSearch').onclick=()=>run(()=>api('search/resume',{confirm:true}),$('#continueSearch'));$('#stopSearch').onclick=()=>run(()=>api('search/stop'));
function reportImport(r){toast(`${r.added} nuevos · ${r.duplicates} ya existentes · ${r.history} envíos recuperados${r.rejected?' · '+r.rejected+' filas rechazadas':''}${r.errors?.length?'. '+r.errors.join(' / '):''}`,r.rejected>0);}
$('#importOpen').onclick=()=>$('#importDialog').showModal();$('#importFile').onchange=()=>run(async()=>{const file=$('#importFile').files[0];if(!file)return;if(file.size>8e6)throw Error('El archivo supera 8 MB.');const format=file.name.toLowerCase().endsWith('.xlsx')?'xlsx':file.name.toLowerCase().endsWith('.csv')?'csv':'json';let content;if(format==='xlsx'){const b=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<b.length;i+=32768)binary+=String.fromCharCode(...b.subarray(i,i+32768));content=btoa(binary);}else content=await file.text();const r=await api('import',{format,content});$('#importDialog').close();$('#importFile').value='';reportImport(r);});
$$('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;$$('[data-view]').forEach(n=>{n.classList.toggle('active',n===b);n.setAttribute('aria-selected',String(n===b));});renderRows();});$('#listSearch').oninput=renderRows;$('#listCountry').onchange=renderRows;$('#selectAll').onchange=e=>{for(const l of filtered().filter(isSelectable)){if(e.target.checked&&selected.size<100)selected.add(l.id);else if(!e.target.checked)selected.delete(l.id);}renderRows();};$('#leadRows').onchange=e=>{const id=Number(e.target.dataset.select);if(!id)return;if(e.target.checked){if(selected.size>=100){e.target.checked=false;toast('La cola admite hasta 100 clientes por vez.',true);return;}selected.add(id);}else selected.delete(id);renderRows();};$('#leadRows').onclick=e=>{const b=e.target.closest('[data-review]');if(b)openLead(Number(b.dataset.review));};
function renderAudit(l){const a=audit(l);$('#hotelAudit').innerHTML=a?`<strong>${esc(a.manual?'Revisado por vos':a.label)}</strong><p>${esc(a.businessDetail||'Actividad comercial pendiente de confirmar.')}</p><p>${esc(a.feedDetail||'Feed pendiente de verificar.')}</p><small>${esc(activityLine(l))}</small><div>${[[a.businessSource,'Actividad comercial'],[a.feedSource,'Evidencia del feed']].filter(x=>/^https?:\/\//.test(x[0]||'')).map(([url,label])=>`<a href="${esc(url)}" target="_blank" rel="noreferrer">${esc(label)} ↗</a>`).join(' · ')}</div>`:`<p>Este contacto todavía no tiene un análisis de actividad comercial y contenido. Revisá el perfil antes de contactar.</p><small>${esc(activityLine(l))}</small>`;$('#manualReviewLabel').hidden=qualified(l);}
function openLead(id){activeLead=id;const l=state.leads.find(l=>l.id===id);$('#proposalName').textContent=displayName(l);$('#proposalLocation').textContent=[l.city,l.country].filter(Boolean).join(' · ');$('#manualReview').checked=false;$('#manualReviewLabel').hidden=qualified(l);$('#proposalText').value=l.message;$('#proposalEmail').value=l.email||'';renderAudit(l);$('#proposalReason').textContent=l.score_reason+' '+l.reason;$('#proposalScore').textContent=`Afinidad ${l.score}/100`;$('#proposalSource').href=l.source;$('#proposalProfile').href=`https://www.instagram.com/${l.handle}/`;$('#doNotContact').checked=!!l.dnc;updateProposalStatus();$('#leadDialog').showModal();}
function updateProposalStatus(){const l=state.leads.find(l=>l.id===activeLead);if(!l)return;const unverified=!qualified(l)&&!$('#manualReview').checked;const blocked=unverified||l.block&&!l.block.startsWith('Revisar hotel')&&!l.block.startsWith('Verificá el hotel');$('#proposalStatus').textContent=l.demo?'Ejemplo ficticio. No se enviarán mensajes reales.':unverified?'Revisá el hotel y su contenido; después marcá la confirmación.':blocked?l.block:'Revisá el perfil y el texto antes de contactar.';$('#copyOpen').disabled=!!blocked;$('#markSent').disabled=!!blocked;$('#copyOpen').textContent=l.demo?'Copiar ejemplo':'Copiar y abrir Instagram ↗';$('#markSent').textContent=l.demo?'Simular envío ✓':'Ya envié por Instagram ✓';const eb=l.emailBlock||'';$('#sendEmailOne').disabled=l.demo||unverified||!state.email.configured||!$('#proposalEmail').value.trim()||!!eb&&!/^(Revisar hotel|Verificá el hotel|Falta el email)/.test(eb);$('#sendEmailOne').textContent=!state.email.configured?'✉ Configurá tu email en Ajustes':'✉ Enviar por email';}
async function saveLead(approve=false){await api('update',{id:activeLead,message:$('#proposalText').value,email:$('#proposalEmail').value,dnc:$('#doNotContact').checked,...($('#manualReview').checked?{qualificationReviewed:true}:{}),...(approve?{approved:true}:{})});}
$('#manualReview').onchange=updateProposalStatus;$('#proposalEmail').oninput=updateProposalStatus;$('#sendEmailOne').onclick=()=>run(async()=>{const to=$('#proposalEmail').value.trim();if(!confirm(`¿Enviar esta propuesta por email a ${to}${state.email.attachment?' con '+state.email.attachment:''}?`))return;await saveLead(true);const r=await api('email/send',{ids:[activeLead],confirm:true});if(r.failed.length)throw Error(r.failed.join(' / '));$('#leadDialog').close();toast('Email enviado. El cliente queda tachado y no se le vuelve a escribir.');},$('#sendEmailOne'));$('#saveProposal').onclick=()=>run(async()=>{await saveLead();toast('Propuesta guardada.');});$('#doNotContact').onchange=()=>run(()=>saveLead());$('#copyOpen').onclick=()=>{const l=state.leads.find(l=>l.id===activeLead);const copied=copyText($('#proposalText').value);if(!l.demo)openChat(l.handle);run(async()=>{await copied.catch(()=>{throw Error('No se pudo copiar. Seleccioná el texto de la propuesta y copialo con Ctrl+C.');});await saveLead(true);toast('Mensaje copiado. En el chat pegalo con Ctrl+V, tocá Enviar y volvé para tocar «Ya lo envié».');});};let manualIds=[];
$('#markSent').onclick=()=>run(async()=>{const l=state.leads.find(l=>l.id===activeLead);if(!confirm(l.demo?'¿Simular este envío ficticio?':`¿Ya enviaste esta propuesta a @${l.handle}?`))return;await saveLead(true);await api('manual',{id:activeLead,confirm:true});$('#leadDialog').close();if(manualIds.length)nextManual();toast('Registrado. El cliente queda tachado y no se le vuelve a escribir.');});
$('#manualInstagramSelection').onclick=()=>run(openManualBatch);
$('#startQueue').onclick=()=>run(async()=>{if(!state.instagram){settings();$('#instagramSettings').open=true;toast('Conectá Instagram para iniciar una tanda automática oficial.',true);return;}const batch=await api('instagram/batch/preview',{ids:[...selected]});$('#queuePreviewSummary').textContent=batch.selected+' seleccionados · '+batch.items.length+' habilitados ahora por Meta y cupo · remitente @'+batch.account.username;$('#queuePreview').innerHTML=batch.items.map(l=>'<article><strong>'+esc(l.name)+' · @'+esc(l.handle)+'</strong><p>'+esc(l.message)+'</p></article>').join('')+batch.skipped.map(l=>'<small>'+esc(state.leads.find(v=>v.id===l.id)?.name||'Cliente')+': '+esc(l.reason)+'</small><br>').join('');$('#queueConsent').checked=false;$('#confirmQueue').disabled=true;$('#confirmQueue').dataset.ids=JSON.stringify(batch.items.map(l=>l.id));$('#confirmQueue').dataset.token=batch.token;$('#confirmQueue').dataset.eligible=String(batch.items.length);$('#queueDialog').showModal();});
$('#queueConsent').onchange=()=>$('#confirmQueue').disabled=!$('#queueConsent').checked||Number($('#confirmQueue').dataset.eligible)===0;
$('#confirmQueue').onclick=()=>run(async()=>{await api('queue/start',{ids:JSON.parse($('#confirmQueue').dataset.ids||'[]'),token:$('#confirmQueue').dataset.token,confirm:$('#queueConsent').checked,reviewed:true});selected.clear();$('#queueDialog').close();toast('Tanda oficial iniciada por prioridad. Se controlan habilitación, cupos e historial antes de cada envío.');},$('#confirmQueue'));
$('#pauseQueue').onclick=()=>run(()=>api('queue/pause'));$('#resumeQueue').onclick=()=>run(()=>api('queue/resume'));
$('#emailSelection').onclick=()=>run(async()=>{if(!state.email.configured){settings();$('#emailSettings').open=true;toast('Configurá tu casilla para enviar emails.',true);return;}const batch=await api('batch/preview',{ids:[...selected],channel:'email'});$('#emailPreviewSummary').textContent=batch.selected+' seleccionados · '+batch.items.length+' en esta tanda por prioridad · '+batch.skipped.length+' omitidos o para después. Adjunto: '+(state.email.attachment||'ninguno');$('#emailPreview').innerHTML=batch.items.map(l=>'<article><strong>'+esc(l.name)+' · '+esc(l.email)+'</strong><p>'+esc(l.message)+'</p></article>').join('');$('#emailConsent').checked=false;$('#confirmEmail').disabled=true;$('#confirmEmail').dataset.token=batch.token;$('#confirmEmail').dataset.ids=JSON.stringify(batch.items.map(l=>l.id));$('#emailDialog').showModal();});$('#emailConsent').onchange=()=>$('#confirmEmail').disabled=!$('#emailConsent').checked||JSON.parse($('#confirmEmail').dataset.ids||'[]').length===0;$('#confirmEmail').onclick=()=>run(async()=>{const ids=JSON.parse($('#confirmEmail').dataset.ids);$('#confirmEmail').textContent='Enviando…';try{const r=await api('email/send',{ids,confirm:true,reviewed:true,token:$('#confirmEmail').dataset.token});selected.clear();$('#emailDialog').close();toast(`${r.sent.length} emails enviados${r.failed.length?' · '+r.failed.length+' sin enviar: '+r.failed.join(' / '):''}`,r.failed.length>0);}finally{$('#confirmEmail').textContent='Enviar emails';}},$('#confirmEmail'));
function settingsFill(){$('#instagramSender').value=state.settings.instagramSender||state.instagram?.username||state.settings.lastSeed?.match(/instagram\.com\/([a-z0-9._]+)/i)?.[1]||'mila.content';$('#smtpHost').value=state.settings.smtpHost;$('#smtpPort').value=String(state.settings.smtpPort);$('#smtpUser').value=state.settings.smtpUser;$('#emailFrom').value=state.settings.emailFrom||state.settings.sender;$('#emailSubject').value=state.settings.emailSubject;$('#emailDaily').value=state.settings.emailDaily;$('#emailMonthly').value=state.settings.emailMonthly;}
$('#emailForm').onsubmit=e=>{e.preventDefault();run(async()=>{const f=Object.fromEntries(new FormData(e.target));await api('email-config',{...f,port:Number(f.port)});e.target.pass.value='';toast('Email conectado. Ya podés enviar propuestas por email.');},e.submitter);};$('#emailLimitsForm').onchange=()=>run(async()=>{await api('settings',{emailDaily:$('#emailDaily').value,emailMonthly:$('#emailMonthly').value});toast('Cupos de email guardados.');});$('#attachmentFile').onchange=()=>run(async()=>{const file=$('#attachmentFile').files[0];if(!file)return;if(file.size>8e6)throw Error('El adjunto debe pesar hasta 8 MB.');const b=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<b.length;i+=32768)binary+=String.fromCharCode(...b.subarray(i,i+32768));await api('attachment',{name:file.name,content:btoa(binary)});$('#attachmentFile').value='';toast('Adjunto guardado. Se enviará con cada email.');});$('#removeAttachment').onclick=()=>run(async()=>{await api('attachment',{remove:true});toast('Adjunto quitado.');});
function settings(){settingsFill();for(const [id,key]of Object.entries({sender:'sender',dailyLimit:'daily',monthlyLimit:'monthly',template:'template'}))$('#'+id).value=state.settings[key];$('#soundPreference').checked=sounds;$('#settingsDialog').showModal();}$('#settingsOpen').onclick=settings;$('#preferencesForm').onsubmit=e=>{e.preventDefault();run(async()=>{await api('settings',Object.fromEntries(new FormData(e.target)));sounds=$('#soundPreference').checked;localStorage.setItem('nexo-sounds',String(sounds));$('#settingsDialog').close();toast('Ajustes guardados.');},e.submitter);};
$('#claudeForm').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);$('#connectionError').textContent='';try{await saveFilters();await api('claude',{key:f.get('key'),remember:f.get('remember')==='on'});e.target.reset();$('#connectionDialog').close();toast('Claude recibió tu configuración y quedó conectado.');if(searchAfterConnect){searchAfterConnect=false;await startSearch();}else{openAssistant();}}catch(err){$('#connectionError').textContent=err.message;}},e.submitter);};$('#igForm').onsubmit=e=>{e.preventDefault();run(async()=>{const f=new FormData(e.target);await api('instagram',{token:f.get('token'),remember:f.get('remember')==='on'});e.target.reset();await api('sync');toast('Instagram conectado.');},e.submitter);};$('#disconnect').onclick=()=>run(async()=>{await api('disconnect');toast('Se borraron las conexiones guardadas.');});$('#profileOpen').onclick=()=>$('#profileDialog').showModal();$('#logout').onclick=()=>run(async()=>{await api('logout');showLogin();loginMode(false);});$('#rulesOpen').onclick=()=>$('#rulesDialog').showModal();
$('#historyOpen').onclick=()=>{const labels={sent:'Enviado',failed:'No enviado',pending:'Pendiente',uncertain:'Revisar resultado'};$('#historyList').innerHTML=state.history.length?state.history.map(e=>`<article class="history-item"><strong>${esc(e.name)} <small>${esc(date(e.at))} · ${esc(labels[e.status])}</small></strong><details><summary>Ver propuesta</summary><p>${esc(e.message)}</p></details>${e.status==='uncertain'?`<div class="two"><button data-reconcile="${e.id}" data-result="sent" class="subtle-button">Verifiqué: se envió</button><button data-reconcile="${e.id}" data-result="failed" class="subtle-button">Verifiqué: no se envió</button></div>`:''}</article>`).join(''):'<p>Todavía no registraste propuestas.</p>';$('#historyDialog').showModal();};$('#historyList').onclick=e=>{const b=e.target.closest('[data-reconcile]');if(b&&confirm('¿Revisaste el resultado real en Instagram?'))run(async()=>{await api('reconcile',{event:Number(b.dataset.reconcile),status:b.dataset.result});$('#historyDialog').close();toast('Historial actualizado.');});};$('#demoButton').onclick=()=>run(async()=>{await api('demo');toast('Tres ejemplos ficticios cargados para probar la planilla.');});$('#clearDemo').onclick=()=>run(()=>api('clear-demo'));$('#downloadExcel').onclick=()=>toast('Descargando tu planilla actualizada.');$('#quitApp').onclick=()=>run(async()=>{if(!confirm('¿Cerrar Nexo? Tus datos quedan guardados.'))return;await api('quit');document.body.innerHTML='<section class="closed"><h1>Nexo está cerrado.</h1><p>Tu planilla quedó guardada. Para volver, abrí Nexo.</p></section>';window.close();});

const SCHEDULE_LABELS={pending:'Programado',due:'Toca enviar',sent:'Enviado',failed:'No enviado',cancelled:'Cancelado'};
function when(v){return new Intl.DateTimeFormat('es-AR',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'}).format(new Date(v));}
function renderSchedules(){const list=state.schedules,open=list.filter(x=>['pending','due'].includes(x.status)),due=list.filter(x=>x.status==='due');$('#updateNotice').hidden=state.build===PAGE_BUILD;$('#scheduledCount').textContent=open.length?String(open.length):'';$('#dueNotice').hidden=!due.length;$('#dueTitle').textContent=`Hoy toca enviar por Instagram a ${due.length} ${due.length===1?'hotel':'hoteles'}`;$('#schedulesList').innerHTML=list.length?list.map(x=>`<article class="history-item"><strong>${esc(x.name)} <small>${esc(when(x.at))} · ${x.channel==='email'?'✉ '+esc(x.email||''):'Instagram @'+esc(x.handle)} · ${esc(SCHEDULE_LABELS[x.status]||x.status)}</small></strong>${x.note&&x.status!=='sent'?`<p class="small-note">${esc(x.note)}</p>`:''}<div class="two">${x.status==='due'?`<button class="subtle-button" data-open-lead="${x.leadId}">Abrir para enviar</button>`:''}${['pending','due'].includes(x.status)?`<button class="text-button" data-cancel-schedule="${x.id}">Cancelar</button>`:''}</div></article>`).join(''):'<p>No hay envíos programados.</p>';}
function localInput(d){const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`;}
function schedulePreview(){const channel=$('#scheduleChannel').value,leads=state.leads.filter(l=>selected.has(l.id));const blocked=l=>{const b=channel==='email'?l.emailBlock:l.block;return b&&!/^(Revisar hotel|Cupo)/.test(b)?b:'';};const ok=leads.filter(l=>!blocked(l));$('#schedulePreviewSummary').textContent=`${leads.length} seleccionados · ${ok.length} se pueden programar por ${channel==='email'?'email':'Instagram'}.`;$('#schedulePreview').innerHTML=leads.map(l=>`<article><strong>${esc(l.name)} · ${esc(channel==='email'?l.email||'sin email':'@'+l.handle)}</strong><p>${esc(l.message)}</p>${blocked(l)?`<small>${esc(blocked(l))}</small>`:''}</article>`).join('');$('#confirmSchedule').dataset.ids=JSON.stringify(ok.map(l=>l.id));$('#confirmSchedule').disabled=!$('#scheduleConsent').checked||!ok.length;}
$('#scheduleSelection').onclick=()=>{const d=new Date(Date.now()+864e5);d.setHours(9,0,0,0);$('#scheduleAt').value=localInput(d);$('#scheduleAt').min=localInput(new Date());$('#scheduleConsent').checked=false;schedulePreview();$('#scheduleDialog').showModal();};$('#scheduleChannel').onchange=schedulePreview;$('#scheduleConsent').onchange=schedulePreview;
$('#confirmSchedule').onclick=()=>run(async()=>{const at=new Date($('#scheduleAt').value);if(!Number.isFinite(at.getTime()))throw Error('Elegí fecha y hora.');const channel=$('#scheduleChannel').value;if(channel==='email'&&!state.email.configured)toast('Acordate de configurar tu email en Ajustes antes de esa hora.',true);const r=await api('schedule',{ids:JSON.parse($('#confirmSchedule').dataset.ids),channel,at:at.toISOString(),confirm:true});selected.clear();$('#scheduleDialog').close();toast(`${r.ok.length} envíos programados para ${when(at)}${r.skipped.length?' · '+r.skipped.length+' omitidos: '+r.skipped.join(' / '):''}`,r.skipped.length>0);},$('#confirmSchedule'));
$('#schedulesOpen').onclick=()=>{$('#autoEmail').checked=!!state.settings.autoEmail;$('#autoEmailTime').value=state.settings.autoEmailTime;$('#autoEmailCount').value=state.settings.autoEmailCount;renderSchedules();$('#schedulesDialog').showModal();};$('#dueOpen').onclick=()=>$('#schedulesOpen').click();
$('#autoEmailForm').onsubmit=e=>{e.preventDefault();run(async()=>{const on=$('#autoEmail').checked;if(on&&!state.email.configured)throw Error('Primero configurá tu email en Ajustes.');await api('settings',{autoEmail:on,autoEmailTime:$('#autoEmailTime').value,autoEmailCount:$('#autoEmailCount').value});toast(on?`Tanda diaria activada: ${$('#autoEmailCount').value} emails a las ${$('#autoEmailTime').value}.`:'Tanda diaria desactivada.');},e.submitter);};
$('#schedulesList').onclick=e=>{const c=e.target.closest('[data-cancel-schedule]');if(c&&confirm('¿Cancelar este envío programado?'))run(()=>api('schedule/cancel',{id:Number(c.dataset.cancelSchedule)}));const o=e.target.closest('[data-open-lead]');if(o){$('#schedulesDialog').close();openLead(Number(o.dataset.openLead));}};

function openAssistant(){renderAssistant();$('#assistantDialog').showModal();$('#assistantDialog').scrollTop=0;$('#assistantLog').scrollTop=$('#assistantLog').scrollHeight;}
function renderAssistant(){if(!state?.assistant)return;const a=state.assistant,key=state.user.id+':'+a.history.length+':'+(a.history.at(-1)?.at||'');if(key!==assistantLogKey){$('#assistantLog').innerHTML=a.history.length?a.history.slice(-6).map(h=>`<article class="assistant-turn"><strong>Vos</strong><p>${esc(h.request)}</p><strong>Claude · acciones de Nexo</strong><p>${esc(h.answer)}</p></article>`).join(''):'<div class="assistant-welcome"><strong>¿Qué hacemos hoy?</strong><p>Puedo buscar hoteles para tu oferta, preparar propuestas y actualizar tu planilla.</p></div>';assistantLogKey=key;$('#assistantLog').scrollTop=$('#assistantLog').scrollHeight;}$('#assistantWorking').hidden=a.status!=='running';$('#assistantStage').textContent=a.stage;$('#sendAssistant').disabled=a.status==='running';$$('[data-assistant]').forEach(b=>b.disabled=a.status==='running');$('#reviewAssistantSelection').hidden=!a.preview?.length;$('#assistantDownload').hidden=!a.download;}
async function askAssistant(text){if(!state.claudeConnected){openConnection();return;}await saveFilters();$('#sendAssistant').disabled=true;$('#assistantWorking').hidden=false;$('#assistantStage').textContent='Enviando tu pedido a Claude…';try{await api('assistant/message',{text});$('#assistantText').value='';}finally{await refresh();}}
$('#assistantForm').onsubmit=e=>{e.preventDefault();run(()=>askAssistant($('#assistantText').value),e.submitter);};$$('[data-assistant]').forEach(b=>b.onclick=()=>run(()=>askAssistant(b.dataset.assistant),b));$('#stopAssistant').onclick=()=>run(()=>api('assistant/pause'));$('#reviewAssistantSelection').onclick=()=>{selected=new Set(state.assistant.preview);$('#assistantDialog').close();renderRows();$('#startQueue').click();};
document.addEventListener('click',e=>{const b=e.target.closest('[data-close]');if(b)$('#'+b.dataset.close).close();});$$('dialog').forEach(d=>d.onclick=e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
setInterval(async()=>{if(!state||polling||document.hidden)return;polling=true;try{await refresh();}catch{}finally{polling=false;}},3000);
(async()=>{try{const session=await(await fetch('/api/session')).json();csrf=session.csrf;loginMode(!session.hasAccounts);if(session.user)await startWorkspace();}catch{toast('No se pudo abrir Nexo. Ejecutá el acceso del escritorio.',true);}})();

$('#messageSettings').onclick=()=>{settings();$('#template').closest('details').open=true;$('#template').focus();};
$('#clearResults').onclick=()=>run(async()=>{if(!confirm('¿Limpiar la planilla? Se quitan todos los clientes a los que todavía no les enviaste nada. Los enviados se conservan en «Enviados» para no repetirlos, y podés recuperar todo con «Restaurar».'))return;const r=await api('results/clear');selected.clear();$$('.more-menu').forEach(m=>m.open=false);toast(r.archived+' resultados limpiados. Los enviados siguen en «Enviados».');});
$('#restoreResults').onclick=()=>run(async()=>{await api('results/restore');$$('.more-menu').forEach(m=>m.open=false);toast('Resultados restaurados.');});
async function openManualBatch(){$('#manualPrep').hidden=false;$('#manualRun').hidden=true;$('#manualBatchHead').textContent='Revisá los mensajes antes de preparar la tanda.';const batch=await api('batch/preview',{ids:[...selected],channel:'instagram'});$('#manualBatchSummary').textContent=batch.selected+' seleccionados · '+batch.items.length+' primeros por prioridad · '+batch.skipped.length+' omitidos o para otra tanda.';$('#manualBatchPreview').innerHTML=batch.items.map(l=>'<article><strong>'+esc(l.name)+' · @'+esc(l.handle)+'</strong><p>'+esc(l.message)+'</p></article>').join('');$('#confirmManualBatch').dataset.token=batch.token;$('#confirmManualBatch').dataset.ids=JSON.stringify(batch.items.map(l=>l.id));$('#manualBatchConsent').checked=false;$('#confirmManualBatch').disabled=true;$('#manualBatchDialog').showModal();}
$('#manualBatchConsent').onchange=()=>$('#confirmManualBatch').disabled=!$('#manualBatchConsent').checked||!JSON.parse($('#confirmManualBatch').dataset.ids||'[]').length;
function nextManual(){const id=manualIds.shift();if(id){openLead(id);$('#proposalStatus').textContent='Tanda: '+(manualIds.length+1)+' restantes. Copiá y abrí Instagram; registrá el envío después de enviarlo.';}else toast('Tanda registrada. El Excel ya está actualizado.');}
$('#confirmManualBatch').onclick=()=>run(async()=>{const batch=await api('batch/manual',{ids:JSON.parse($('#confirmManualBatch').dataset.ids),reviewed:true,token:$('#confirmManualBatch').dataset.token});runItems=batch.items.map(l=>({id:l.id,name:displayName(l),handle:l.handle,message:l.message,status:'pending'}));selected.clear();renderRows();$('#manualPrep').hidden=true;$('#manualRun').hidden=false;$('#manualBatchHead').textContent='Abrí cada chat, enviá el mensaje y marcalo como enviado.';renderRun();});

let instagramTestNonce='';
function renderOfficialInstagram(){const c=state.officialInstagram||{},pending=['waiting','connecting'].includes(c.status);$('#officialInstagramStatus').textContent=c.status==='failed'?c.message:pending?c.message:state.instagram?'Conectado: @'+state.instagram.username+(c.expiresAt?' · autorización hasta '+date(new Date(c.expiresAt).toISOString()):''):c.setupError||(!c.configured?'Pendiente: configuración inicial de Nexo en Meta.':c.message||'Listo para autorizar tu cuenta profesional.');$('#officialInstagramSetup').hidden=!!c.configured||!!state.instagram;$('#connectOfficialInstagram').disabled=pending;$('#connectOfficialInstagram').textContent=state.instagram?'Volver a autorizar Instagram ↗':'Conectar Instagram ↗';$('#cancelOfficialInstagram').hidden=!pending;$('#disconnectInstagram').hidden=!state.instagram;$('#instagramTestOpen').disabled=!state.instagram||pending;}
$('#connectOfficialInstagram').onclick=()=>{if(!state.officialInstagram?.configured){toast('La conexión está preparada. Falta configurar la aplicación de Meta y el servicio de autorización de Nexo.',true);return;}const username=$('#instagramSender').value.trim().replace(/^@/,'');const popup=window.open('about:blank','_blank');if(!popup){toast('Permití abrir la ventana de autorización de Instagram.',true);return;}popup.opener=null;run(async()=>{try{const r=await api('instagram/oauth/start',{username});popup.location.href=r.authorizationUrl;toast('Autorizá tu cuenta en la página oficial. Nexo comprobará la conexión al terminar.');}catch(e){popup.close();throw e;}},$('#connectOfficialInstagram'));};
$('#cancelOfficialInstagram').onclick=()=>run(()=>api('instagram/oauth/cancel'));$('#disconnectInstagram').onclick=()=>run(async()=>{await api('instagram/disconnect');toast('Instagram desconectado. Tu historial y las otras conexiones se conservan.');});
function resetInstagramTest(){instagramTestNonce='';$('#instagramTestPreview').hidden=true;$('#instagramTestConsent').checked=false;$('#instagramTestConsent').disabled=true;$('#sendInstagramTest').disabled=true;$('#instagramTestResult').textContent='';}
$('#instagramTestOpen').onclick=()=>{resetInstagramTest();$('#instagramTestTarget').value='';$('#instagramTestFrom').textContent='Cuenta remitente: @'+state.instagram.username;$('#instagramTestDialog').showModal();};$('#instagramTestTarget').oninput=resetInstagramTest;$('#instagramTestText').oninput=resetInstagramTest;
$('#prepareInstagramTest').onclick=()=>run(async()=>{resetInstagramTest();const r=await api('instagram/test/preview',{target:$('#instagramTestTarget').value,text:$('#instagramTestText').value});instagramTestNonce=r.preview.nonce;$('#instagramTestPreview').textContent='De @'+r.preview.from+' a @'+r.preview.target+'\n\n'+r.preview.text;$('#instagramTestPreview').style.whiteSpace='pre-wrap';$('#instagramTestPreview').hidden=false;$('#instagramTestConsent').disabled=false;},$('#prepareInstagramTest'));
$('#instagramTestConsent').onchange=()=>$('#sendInstagramTest').disabled=!instagramTestNonce||!$('#instagramTestConsent').checked;
$('#sendInstagramTest').onclick=()=>run(async()=>{const nonce=instagramTestNonce;instagramTestNonce='';$('#sendInstagramTest').disabled=true;const r=await api('instagram/test/send',{nonce,confirm:$('#instagramTestConsent').checked});$('#instagramTestConsent').disabled=true;$('#instagramTestConsent').checked=false;$('#instagramTestResult').textContent='Meta confirmó el mensaje a @'+r.to+'. Historial y Excel actualizados.';toast('Mensaje de prueba confirmado por Meta.');},$('#sendInstagramTest'));

