$('#testSendGo').onclick=()=>{const target=$('#testSendTarget').value.trim().replace(/^@/,'').replace(/^https?:\/\/(www\.)?instagram\.com\//i,'').replace(/\/.*$/,'').toLowerCase();if(!/^[a-z0-9._]{1,30}$/.test(target)){toast('Escribí una cuenta de Instagram válida, por ejemplo mila.content.',true);return;}const copied=copyText($('#testSendText').value);openChat(target);run(async()=>{await copied.catch(()=>{throw Error('No se pudo copiar. Seleccioná el mensaje y copialo con Ctrl+C.');});$('#testSendDone').hidden=false;toast('Mensaje copiado. En el chat de @'+target+' pegalo con Ctrl+V y tocá Enviar.');});};
