const GUIDE_MS=7500;let guideIndex=0,guidePlaying=true,guideTimers=[],guideStart=0,guideRaf=0;
function guideEl(i,key){return $(`#guideStage .scene[data-scene="${i}"] [data-g="${key}"]`);}
function guideMove(el,click){const st=$('#guideStage').getBoundingClientRect(),r=el.getBoundingClientRect(),c=$('#guideCursor');c.style.left=(r.left-st.left+r.width/2-11)+'px';c.style.top=(r.top-st.top+r.height/2-11)+'px';if(click){setTimeout(()=>{c.classList.remove('click');void c.offsetWidth;c.classList.add('click');el.classList.add('hl');},900);}}
function guideReset(i){const sc=$(`#guideStage .scene[data-scene="${i}"]`);sc.querySelectorAll('.appear').forEach(e=>e.classList.remove('in'));sc.querySelectorAll('.box').forEach(e=>e.classList.remove('ck'));sc.querySelectorAll('.hl').forEach(e=>e.classList.remove('hl'));for(const [act,key,val] of GUIDE[i].a){if(act==='type'){const e=guideEl(i,key);e.textContent='';e.classList.remove('typing');}if(act==='set'){const e=guideEl(i,key);e.dataset.orig=e.dataset.orig||e.textContent;e.textContent=e.dataset.orig;}}const c=$('#guideCursor');c.style.transition='none';c.style.left='50%';c.style.top='105%';void c.offsetWidth;c.style.transition='';}
function guideRun(i){guideTimers.forEach(clearTimeout);guideTimers=[];guideReset(i);let t=500;for(const [act,key,val] of GUIDE[i].a){const e=guideEl(i,key);if(act==='show'){guideTimers.push(setTimeout(()=>e.classList.add('in'),t));t+=900;continue;}guideTimers.push(setTimeout(()=>guideMove(e,act!=='move'),t));t+=1000;if(act==='type'){guideTimers.push(setTimeout(()=>{e.classList.add('typing');let n=0;const tick=()=>{e.textContent=val.slice(0,++n);if(n<val.length)guideTimers.push(setTimeout(tick,45));else setTimeout(()=>e.classList.remove('typing'),400);};tick();},t));t+=val.length*45+500;}else if(act==='set'){guideTimers.push(setTimeout(()=>{e.textContent=val;e.classList.add('hl');},t));t+=600;}else if(act==='check'){guideTimers.push(setTimeout(()=>e.classList.add('ck'),t));t+=400;}else if(act==='click'){t+=500;}}}
function guideShow(i){guideIndex=(i+GUIDE.length)%GUIDE.length;const g=GUIDE[guideIndex];$$('#guideStage .scene').forEach(s=>s.classList.toggle('on',Number(s.dataset.scene)===guideIndex));$('#guideKicker').textContent=g.k;$('#guideTitle').textContent=g.t;$('#guideText').textContent=g.p;$('#guideCount').textContent=(guideIndex+1)+' de '+GUIDE.length;$('#guideNext').textContent=guideIndex===GUIDE.length-1?'Empezar a usar Nexo ✓':'Siguiente →';$$('#guideProgress i').forEach((b,n)=>{b.classList.toggle('done',n<guideIndex);b.firstChild.style.width=n<guideIndex?'100%':'0';});guideRun(guideIndex);guideStart=performance.now();}
function guideLoop(now){if(!$('#guideDialog').open)return;const bar=$$('#guideProgress i')[guideIndex]?.firstChild;if(guidePlaying){const p=Math.min(1,(now-guideStart)/GUIDE_MS);if(bar)bar.style.width=(p*100)+'%';if(p>=1){if(guideIndex<GUIDE.length-1)guideShow(guideIndex+1);else{guidePlaying=false;$('#guidePlay').textContent='↺ Ver de nuevo';}}}else guideStart=now-(parseFloat(bar?.style.width||0)/100)*GUIDE_MS;guideRaf=requestAnimationFrame(guideLoop);}
function openGuide(){$('#guideProgress').innerHTML=GUIDE.map(()=>'<i><b></b></i>').join('');$$('#guideProgress i').forEach((b,n)=>b.onclick=()=>guideShow(n));guidePlaying=true;$('#guidePlay').textContent='⏸ Pausar';$('#guideDialog').showModal();guideShow(0);cancelAnimationFrame(guideRaf);guideRaf=requestAnimationFrame(guideLoop);try{localStorage.setItem('nexo-guide-seen','1');}catch{}}
$('#guideOpen').onclick=openGuide;
$('#guidePrev').onclick=()=>guideShow(guideIndex-1);
$('#guideNext').onclick=()=>{if(guideIndex===GUIDE.length-1){$('#guideDialog').close();return;}guideShow(guideIndex+1);};
$('#guidePlay').onclick=()=>{if(!guidePlaying&&guideIndex===GUIDE.length-1&&$('#guidePlay').textContent.startsWith('↺')){guidePlaying=true;$('#guidePlay').textContent='⏸ Pausar';guideShow(0);return;}guidePlaying=!guidePlaying;$('#guidePlay').textContent=guidePlaying?'⏸ Pausar':'▶ Reproducir';if(guidePlaying)guideRun(guideIndex);};
$('#guideDialog').addEventListener('close',()=>{guideTimers.forEach(clearTimeout);cancelAnimationFrame(guideRaf);});
// First visit: show the guide once after entering.
new MutationObserver(()=>{let seen='1';try{seen=localStorage.getItem('nexo-guide-seen');}catch{}if(!seen&&!$('#workspace').hidden&&!$('#guideDialog').open)setTimeout(openGuide,600);}).observe($('#workspace'),{attributes:true,attributeFilter:['hidden']});

// Close the "Más" menu after choosing an option or clicking outside.
document.addEventListener('click',e=>{$$('.more-menu[open]').forEach(m=>{if(!m.contains(e.target)||e.target.closest('.menu-item'))m.open=false;});});

// Batch run panel: every client of the batch with its own "open chat" and "sent" buttons.
let runItems=[];
function renderRun(){const done=runItems.filter(i=>i.status==='sent').length;$('#runCount').textContent=`${done} de ${runItems.length} enviados`;const opened=runItems.filter(i=>i.status==='opened').length,pending=runItems.filter(i=>i.status==='pending').length;$('#runOpenAll').disabled=!pending;$('#runOpenAll').textContent=pending?`Abrir ${pending===runItems.length?'los '+pending:'los '+pending+' restantes'} en Chrome`:'Todos los chats abiertos';$('#runMarkAll').disabled=!opened;$('#runMarkAll').textContent=opened?`Marcar ${opened} como enviados`:'Marcar como enviados';$('#runBar').className='w'+Math.round(done/Math.max(1,runItems.length)*10);$('#runList').innerHTML=runItems.map((i,n)=>`<li class="run-item ${i.status}"><span class="run-num">${i.status==='sent'?'✓':n+1}</span><div class="run-main"><strong>${esc(i.name)}</strong><small>@${esc(i.handle)} · ${i.status==='sent'?'Enviado y registrado':i.status==='skipped'?'Salteada: publica seguido':i.status==='opened'?'Chat abierto · pegá el mensaje y enviá':'Listo para abrir'}</small><details><summary>Ver mensaje</summary><p>${esc(i.message)}</p></details></div><div class="run-actions">${i.status==='sent'||i.status==='skipped'?'':`<button class="text-button compact" data-run-active="${n}" title="Si publicó en el último mes no le escribas">Publica seguido</button><button class="subtle-button compact" data-run-open="${n}">${i.status==='opened'?'↻ Abrir de nuevo':'Abrir chat ↗'}</button><button class="primary compact" data-run-sent="${n}" ${i.status==='opened'?'':'disabled'}>Ya lo envié ✓</button>`}</div></li>`).join('');if(runItems.length&&done+runItems.filter(i=>i.status==='skipped').length===runItems.length)toast('¡Tanda completa! Los enviados quedan tachados en el Excel.');}
$('#runList').onclick=e=>{const act=e.target.closest('[data-run-active]');if(act){const i=runItems[Number(act.dataset.runActive)];if(!confirm(`¿@${i.handle} publicó en el último mes? Se saltea y no se le escribe.`))return;run(async()=>{await api('activity',{id:i.id,active:true});i.status='skipped';renderRun();toast('@'+i.handle+' salteada: publica seguido.');});return;}const o=e.target.closest('[data-run-open]'),s=e.target.closest('[data-run-sent]');if(o){const i=runItems[Number(o.dataset.runOpen)];const copied=copyText(i.message);openChat(i.handle);i.status='opened';renderRun();copied.then(()=>toast('Mensaje copiado. En el chat de @'+i.handle+' pegalo con Ctrl+V y tocá Enviar.')).catch(()=>toast('No se pudo copiar: abrí «Ver mensaje» y copialo con Ctrl+C.',true));}if(s){const i=runItems[Number(s.dataset.runSent)];if(!confirm('¿Ya enviaste el mensaje a @'+i.handle+' desde Instagram?'))return;run(async()=>{await api('manual',{id:i.id,confirm:true});i.status='sent';renderRun();});}};

// Step-by-step screens: only one panel is visible at a time.
let currentStep=0;
function setStep(n,scroll=true){n=Number(n);if(n===3&&!selected.size){toast('Primero marcá en el paso 2 los clientes a los que querés enviarles.');n=2;}if(n===2&&!state?.leads?.some(l=>!l.archived)&&!['running','waiting'].includes(state?.search?.status)){toast('Todavía no hay clientes. Empezá buscando en el paso 1.');n=1;}currentStep=n;document.body.dataset.step=String(n);renderSteps();if(scroll)window.scrollTo({top:0,behavior:'smooth'});}
function renderSteps(){if(!state)return;const hasLeads=state.leads.some(l=>!l.archived);if(!currentStep){currentStep=hasLeads?2:1;document.body.dataset.step=String(currentStep);}[1,2,3].forEach(n=>{const s=$('#step'+n);s.classList.toggle('active',n===currentStep);s.classList.toggle('done',n<currentStep||(n===1&&hasLeads)||(n===2&&selected.size>0&&currentStep!==2));s.querySelector('b').textContent=s.classList.contains('done')&&n!==currentStep?'✓':String(n);});
 $('#nextAction').innerHTML=currentStep===1?'<b>Paso 1 ·</b> Revisá tu Instagram y los filtros, y tocá <b>«Buscar»</b>.':currentStep===2?'<b>Paso 2 ·</b> Tocá «Ver» para revisar y <b>marcá la casilla</b> de los clientes que quieras contactar.':'<b>Paso 3 ·</b> Elegí <b>cómo enviarles</b> tu propuesta.';
 $('#toStep2').hidden=!hasLeads;$('#toStep2').textContent=['running','waiting'].includes(state.search.status)?'Ver los clientes que van apareciendo →':'Ya tengo clientes · ver resultados →';$('#toStep3').disabled=!selected.size;$('#toStep3').textContent=selected.size?`Continuar a enviar (${selected.size}) →`:'Marcá clientes para continuar';
 const chosen=state.leads.filter(l=>selected.has(l.id));$('#sendSummary').textContent=chosen.length?`${chosen.length} ${chosen.length===1?'cliente elegido':'clientes elegidos'} · ${chosen.filter(l=>l.email).length} con email. Nada se envía sin tu confirmación.`:'Elegí un canal. Nada se envía sin tu confirmación.';$('#sendChips').innerHTML=chosen.slice(0,12).map(l=>`<span class="chip">${esc(displayName(l))}<small>@${esc(l.handle)}</small></span>`).join('')+(chosen.length>12?`<span class="chip more">+${chosen.length-12} más</span>`:'');$('#sendEmpty').hidden=!!chosen.length;$('.send-options').hidden=!chosen.length;if(currentStep===3&&!chosen.length){currentStep=2;document.body.dataset.step='2';}}
document.addEventListener('click',e=>{const g=e.target.closest('[data-goto]');if(g){e.preventDefault();setStep(g.dataset.goto);}});
$('#toStep2').onclick=()=>setStep(2);$('#toStep3').onclick=()=>setStep(3);
$$('.steps li').forEach(li=>{li.onclick=()=>setStep(li.dataset.step);li.onkeydown=e=>{if(e.key==='Enter')setStep(li.dataset.step);};});

// Several sectors: chips grouped as lodging / other businesses.
let segments=['Hoteles'],segDraft=new Set();
const LODGING=['Hoteles','Hoteles boutique','Resorts','Posadas','Apart hoteles','Hostales'];
function segmentSummary(){$('#segmentSummary').textContent=segments.length>2?segments.slice(0,2).join(', ')+` y ${segments.length-2} más`:segments.join(' y ');$('#tierField').hidden=!segments.some(x=>LODGING.includes(x));}
function segmentOptions(){const group=(title,list)=>`<div class="seg-group"><h3>${title}</h3><div class="seg-chips">${list.map(x=>`<button type="button" class="seg-chip ${segDraft.has(x)?'on':''}" data-seg="${esc(x)}">${segDraft.has(x)?'✓ ':''}${esc(x)}</button>`).join('')}</div></div>`;$('#segmentOptions').innerHTML=group('Alojamiento',SEGMENTS.filter(x=>LODGING.includes(x)))+group('Otros negocios',SEGMENTS.filter(x=>!LODGING.includes(x)));$('#segmentCount').textContent=segDraft.size?segDraft.size+(segDraft.size===1?' rubro elegido':' rubros elegidos'):'Elegí al menos uno';$('#applySegments').disabled=!segDraft.size;}
$('#segmentOpen').onclick=()=>{segDraft=new Set(segments);segmentOptions();$('#segmentsDialog').showModal();};
$('#segmentOptions').onclick=e=>{const b=e.target.closest('[data-seg]');if(!b)return;const x=b.dataset.seg;segDraft.has(x)?segDraft.delete(x):segDraft.add(x);segmentOptions();};
$('#applySegments').onclick=()=>run(async()=>{segments=SEGMENTS.filter(x=>segDraft.has(x));await api('settings',{segment:segments.join(', ')});segmentSummary();$('#segmentsDialog').close();});

// Plain-language search summary (the technical counters stay out of sight).
function friendlyStatus(){const q=state.search;if(!q||q.status==='idle')return;const n=q.found||0;if(q.status==='running'){$('#searchStatusTitle').textContent=`Buscando… ${n} ${n===1?'negocio encontrado':'negocios encontrados'}`;$('#searchStatusDetail').textContent='Podés ir viendo los resultados en el paso 2 mientras sigue buscando.';}else if(q.status==='waiting'){$('#searchStatusDetail').textContent='El buscador pidió una verificación: completala en la ventana de Edge y tocá «Ya completé la verificación».';}else if(!q.error){$('#searchStatusTitle').textContent=`Listo: ${n} ${n===1?'negocio guardado':'negocios guardados'}`;$('#searchStatusDetail').textContent=n?'Pasá al paso 2 para revisarlos y elegir a quién escribirle.':'No se encontraron negocios con estos filtros. Probá con otra ciudad o más rubros.';}}

// Subtle count of clients found, in the header and on step 2.
function renderCounter(){const active=state.leads.filter(l=>!l.archived),n=active.length,ready=active.filter(isPending).length;$('#leadCounter').hidden=!n;$('#leadCounter').innerHTML=`<b>${n}</b> ${n===1?'cliente':'clientes'}${ready?` · ${ready} ${ready===1?'listo':'listos'}`:''}`;$('#step2Count').hidden=!n;$('#step2Count').textContent=n;}
// Accounts that no longer exist leave the list and are never contacted.
$('#accountGone').onclick=()=>run(async()=>{const l=state.leads.find(x=>x.id===activeLead);if(!l||!confirm(`¿Quitar @${l.handle}? Queda marcada para no volver a contactarla.`))return;await api('update',{id:l.id,dnc:true});selected.delete(l.id);$('#leadDialog').close();toast('Listo: @'+l.handle+' se quitó de tus clientes.');});

// Daily batch: pick the next N clients that never received a message (highest affinity first).
const nextUncontacted=()=>state.leads.filter(l=>!l.archived&&!l.demo&&!l.dnc&&!l.eventStatus&&!isActive(l)).sort((a,b)=>b.score-a.score||a.id-b.id);
function batchLimit(){const left=Math.max(0,Math.min(state.settings.daily-state.counts.daily,state.settings.monthly-state.counts.monthly));return left;}
function renderBatchPicker(){if(!state)return;const n=Number($('#batchSize').value),left=batchLimit(),avail=nextUncontacted().length;[...$('#batchSize').options].forEach(o=>o.disabled=Number(o.value)>state.settings.daily);const take=Math.min(n,left,avail);$('#pickBatch').textContent=!left?'Cupo de hoy completo':!avail?'No hay clientes nuevos':`Marcar los próximos ${take}`;$('#pickBatch').disabled=!take;$('#pickBatch').title=`Hoy podés enviar ${left} más (máximo ${state.settings.daily} por día).`;}
try{const saved=localStorage.getItem('nexo-batch-size');if(saved)$('#batchSize').value=saved;}catch{}
$('#batchSize').onchange=()=>{try{localStorage.setItem('nexo-batch-size',$('#batchSize').value);}catch{}renderBatchPicker();};
$('#pickBatch').onclick=()=>{const take=Math.min(Number($('#batchSize').value),batchLimit());const list=nextUncontacted().slice(0,take);selected=new Set(list.map(l=>l.id));renderRows();toast(`${list.length} clientes marcados. Tocá «Continuar a enviar».`);};

// One-click batch: copy the message once and open every chat in Chrome, then mark the opened ones as sent.
$('#runOpenAll').onclick=()=>run(async()=>{const todo=runItems.filter(i=>i.status==='pending');if(!todo.length)return;const same=todo.every(i=>i.message===todo[0].message);await copyText(todo[0].message).catch(()=>{});toast(same?`Mensaje copiado. Se abren ${todo.length} chats en Chrome: en cada uno pegá con Ctrl+V y tocá Enter.`:'Los mensajes son distintos: usá «Abrir chat» en cada cliente para copiar el suyo.',!same);if(!same)return;for(const i of todo){await openChat(i.handle);i.status='opened';renderRun();await new Promise(r=>setTimeout(r,1200));}},$('#runOpenAll'));
$('#runMarkAll').onclick=()=>run(async()=>{const list=runItems.filter(i=>i.status==='opened');if(!list.length||!confirm(`¿Enviaste el mensaje en los ${list.length} chats que se abrieron? Solo marcá los que realmente enviaste.`))return;for(const i of list){await api('manual',{id:i.id,confirm:true});i.status='sent';renderRun();}toast(`${list.length} clientes marcados como contactados. No se les vuelve a escribir.`);},$('#runMarkAll'));

$('#markActive').onclick=()=>run(async()=>{const l=state.leads.find(x=>x.id===activeLead);if(!l||!confirm(`¿@${l.handle} publica seguido? No se le va a escribir.`))return;await api('activity',{id:l.id,active:true});selected.delete(l.id);$('#leadDialog').close();toast('@'+l.handle+' queda como cuenta activa: no se le escribe.');});
